# -- bookkeeping -----------------------------------------------------

def add_result(self, e, p, status, reason, at, frame):
    self.results.append({
        "event": e,
        "packet": p,
        "status": status,
        "reason": reason,
        "at_ms": at,
        "frame": frame,
    })

def terminate(self, state, code, at, e, p, f, peer=None):
    self.state = state
    self.code = code
    self.at_ms = at
    self.source = {"event": e, "packet": p, "frame": f}
    self.peer_code = peer
    # Any already pending packets are dropped at termination time.
    if self.pending:
        for job in self.pending:
            self.add_result(job["e"], job["p"], "dropped",
                            "CONNECTION_CLOSED", at, None)
        self.pending = []

def fail_packet(self, e, p, at, frame, code):
    self.terminate("closed", code, at, e, p, frame)
    self.add_result(e, p, "error", code, at, frame)

# -- event loop ------------------------------------------------------

def run(self, events):
    for e, ev in enumerate(events):
        t = ev["t"]
        if (self.state == "open" and self.idle_ms != 0 and
                t >= self.last_activity + self.idle_ms):
            self.terminate("idle", "IDLE_TIMEOUT",
                           self.last_activity + self.idle_ms,
                           e, None, None)
        op = ev["op"]
        if op == "datagram":
            self.handle_datagram(e, ev, t)
        elif op == "key":
            if self.state == "open":
                self.handle_key(e, ev, t)
        # tick: nothing to do (idle was checked above)

    # EOF: no extra time passes.  Still-pending packets are buffered.
    if self.pending:
        for job in self.pending:
            self.add_result(job["e"], job["p"], "buffered", "NO_KEYS",
                            job["arrival"], None)
        self.pending = []
    return self.build_result()

def handle_key(self, e, ev, t):
    lvl = ev["level"]
    token = ev["action"]
    if token == "discard":
        self.keys[lvl] = "discarded"
        if self.pending:
            remaining = []
            for job in self.pending:
                if job["level"] == lvl:
                    self.add_result(job["e"], job["p"], "dropped",
                                    "KEYS_DISCARDED", t, None)
                else:
                    remaining.append(job)
            self.pending = remaining
    else:  # install
        if self.keys[lvl] == "absent":
            self.keys[lvl] = "live"
            self.drain_level(lvl, t)
        # installing live/discarded is a no-op

def drain_level(self, lvl, t):
    # Process matching pending packets in original arrival order.
    while self.state == "open":
        idx = -1
        for i, job in enumerate(self.pending):
            if job["level"] == lvl:
                idx = i
                break
        if idx < 0:
            break
        job = self.pending.pop(idx)
        self.process_packet(job["e"], job["p"], job["pkt"], t,
                            job["size"], drained=True)

def handle_datagram(self, e, ev, t):
    packets = ev["packets"]
    if self.state != "open":
        for p in range(len(packets)):
            self.add_result(e, p, "dropped", "CONNECTION_CLOSED", t, None)
        return
    # Normalized short-header boundary policy: any non-final A packet
    # makes the whole datagram's packet layout invalid.
    for p in range(len(packets) - 1):
        if packets[p]["level"] == "A":
            for q in range(len(packets)):
                self.add_result(e, q, "dropped", "LAYOUT", t, None)
            return
    size = ev["bytes"]
    for p, pkt in enumerate(packets):
        if self.state != "open":
            self.add_result(e, p, "dropped", "CONNECTION_CLOSED", t, None)
            continue
        self.process_packet(e, p, pkt, t, size, drained=False)

# -- packet processing ----------------------------------------------

def process_packet(self, e, p, pkt, t, size, drained):
    lvl = pkt["level"]
    pn = pkt["pn"]
    auth = pkt["auth"]

    if not drained:
        if lvl == "I" and size < 1200:
            self.add_result(e, p, "dropped", "INITIAL_TOO_SMALL", t, None)
            return
        if lvl == "Z" and not self.early:
            self.add_result(e, p, "dropped", "EARLY_REJECTED", t, None)
            return

    kstate = self.keys[lvl]
    if kstate == "discarded":
        self.add_result(e, p, "dropped", "KEYS_DISCARDED", t, None)
        return
    if kstate == "absent":
        if len(self.pending) < self.buffer_packets:
            self.pending.append({
                "e": e, "p": p, "arrival": t,
                "pkt": pkt, "level": lvl, "size": size,
            })
        else:
            self.add_result(e, p, "dropped", "BUFFER_FULL", t, None)
        return

    if not auth:
        self.add_result(e, p, "dropped", "AUTH", t, None)
        return

    if lvl == "I":
        pnset = self.pnsets["I"]
    elif lvl == "H":
        pnset = self.pnsets["H"]
    else:
        pnset = self.pnsets["A"]  # Z and A share the Application PN space
    if pn in pnset:
        self.add_result(e, p, "duplicate", "DUPLICATE", t, None)
        return

    self.process_frames(e, p, t, pkt, pnset)

# -- frame preflight and semantics ----------------------------------

def process_frames(self, e, p, t, pkt, pnset):
    lvl = pkt["level"]
    frames = pkt["frames"]

    if not frames:
        self.fail_packet(e, p, t, None, "FRAME_ENCODING_ERROR")
        return

    # Preflight: entire array, in order.
    for fi, fr in enumerate(frames):
        typ = fr["type"]
        if typ == "UNKNOWN":
            self.fail_packet(e, p, t, fi, "FRAME_ENCODING_ERROR")
            return
        if not _frame_allowed(typ, lvl, fr):
            self.fail_packet(e, p, t, fi, "PROTOCOL_VIOLATION")
            return

    # Semantic processing is atomic for this packet.
    journal = []
    overlap = self.overlap
    max_stream_data = self.max_stream_data
    max_data = self.max_data
    crypto_limit = self.crypto_limit

    def set_attr(obj, name, val):
        journal.append(("a", obj, name, obj[name]))
        obj[name] = val

    def put_byte(d, off, val):
        journal.append(("b", d, off, d.get(off, _MISSING)))
        d[off] = val

    def create_stream(sid):
        ent = {
            "id": sid,
            "highest": 0,
            "final_size": None,
            "reset": False,
            "stopped": False,
            "bytes": {},
        }
        self.streams[sid] = ent
        journal.append(("c", sid))
        return ent

    def rollback():
        for op in reversed(journal):
            kind = op[0]
            if kind == "a":
                op[1][op[2]] = op[3]
            elif kind == "b":
                d, off, old = op[1], op[2], op[3]
                if old is _MISSING:
                    del d[off]
                else:
                    d[off] = old
            else:  # "c"
                self.streams.pop(op[1], None)

    def store_bytes(bmap, offset, data, fi):
        for i, b in enumerate(data):
            off = offset + i
            old = bmap.get(off, _MISSING)
            if old is not _MISSING:
                if old != b:
                    if overlap == "reject":
                        raise ProtoError("PROTOCOL_VIOLATION", fi)
                    # overlap == "first": keep the earlier byte
            else:
                put_byte(bmap, off, b)

    def dir_count(sid, allow_uni):
        m = sid & 3
        if m == 0:
            lim = self.max_streams_bidi
        elif m == 2 and allow_uni:
            lim = self.max_streams_uni
        else:
            raise ProtoError("STREAM_STATE_ERROR", fi)
        if (sid >> 2) + 1 > lim:
            raise ProtoError("STREAM_LIMIT_ERROR", fi)

    fi = -1
    try:
        for fi, fr in enumerate(frames):
            typ = fr["type"]
            if typ == "PADDING" or typ == "PING":
                continue

            if typ == "CLOSE":
                # Commit prior effects and this packet, then terminate.
                pnset.add(pkt["pn"])
                self.last_activity = t
                if fr["app"]:
                    code = "PEER_APPLICATION_CLOSE"
                else:
                    code = "PEER_TRANSPORT_CLOSE"
                self.terminate("closed", code, t, e, p, fi,
                               peer=fr["code"])
                self.add_result(e, p, "accepted", "OK", t, None)
                return

            if typ == "ACK":
                ranges = fr["ranges"]
                if not ranges:
                    raise ProtoError("FRAME_ENCODING_ERROR", fi)
                prev_high = None
                for lo, hi in ranges:
                    if lo > hi:
                        raise ProtoError("FRAME_ENCODING_ERROR", fi)
                    if prev_high is not None and lo <= prev_high + 1:
                        raise ProtoError("FRAME_ENCODING_ERROR", fi)
                    prev_high = hi
                sent = self.sent[lvl]
                lows = self.sent_lows[lvl]
                for lo, hi in ranges:
                    idx = bisect.bisect_right(lows, lo) - 1
                    if idx < 0 or hi > sent[idx][1]:
                        raise ProtoError("PROTOCOL_VIOLATION", fi)
                continue

            if typ == "CRYPTO":
                data = bytes.fromhex(fr["data_hex"])
                end = fr["offset"] + len(data)
                if end > MAX_OFF:
                    raise ProtoError("FRAME_ENCODING_ERROR", fi)
                if end > crypto_limit:
                    raise ProtoError("CRYPTO_BUFFER_EXCEEDED", fi)
                st = self.crypto[lvl]
                store_bytes(st["bytes"], fr["offset"], data, fi)
                if end > st["highest"]:
                    set_attr(st, "highest", end)
                continue

            if typ == "STREAM":
                sid = fr["id"]
                dir_count(sid, True)
                ent = self.streams.get(sid)
                if ent is None:
                    ent = create_stream(sid)
                data = bytes.fromhex(fr["data_hex"])
                end = fr["offset"] + len(data)
                fin = fr["fin"]
                if end > MAX_OFF:
                    raise ProtoError("FRAME_ENCODING_ERROR", fi)
                fs = ent["final_size"]
                if fs is not None and (end > fs or (fin and end != fs)):
                    raise ProtoError("FINAL_SIZE_ERROR", fi)
                old_highest = ent["highest"]
                if fin and end < old_highest:
                    raise ProtoError("FINAL_SIZE_ERROR", fi)
                if end > max_stream_data:
                    raise ProtoError("FLOW_CONTROL_ERROR", fi)
                new_highest = end if end > old_highest else old_highest
                new_total = self.tot["v"] - old_highest + new_highest
                if new_total > max_data:
                    raise ProtoError("FLOW_CONTROL_ERROR", fi)
                if not ent["reset"]:
                    store_bytes(ent["bytes"], fr["offset"], data, fi)
                if new_highest != old_highest:
                    set_attr(ent, "highest", new_highest)
                if new_total != self.tot["v"]:
                    set_attr(self.tot, "v", new_total)
                if fin:
                    set_attr(ent, "final_size", end)
                continue

            if typ == "RESET_STREAM":
                sid = fr["id"]
                dir_count(sid, True)
                ent = self.streams.get(sid)
                if ent is None:
                    ent = create_stream(sid)
                size = fr["final_size"]
                fs = ent["final_size"]
                if fs is not None and size != fs:
                    raise ProtoError("FINAL_SIZE_ERROR", fi)
                old_highest = ent["highest"]
                if size < old_highest:
                    raise ProtoError("FINAL_SIZE_ERROR", fi)
                if size > max_stream_data:
                    raise ProtoError("FLOW_CONTROL_ERROR", fi)
                new_highest = size if size > old_highest else old_highest
                new_total = self.tot["v"] - old_highest + new_highest
                if new_total > max_data:
                    raise ProtoError("FLOW_CONTROL_ERROR", fi)
                if new_highest != old_highest:
                    set_attr(ent, "highest", new_highest)
                if new_total != self.tot["v"]:
                    set_attr(self.tot, "v", new_total)
                set_attr(ent, "final_size", size)
                set_attr(ent, "reset", True)
                continue

            if typ == "STOP_SENDING":
                sid = fr["id"]
                if (sid & 3) != 0:
                    raise ProtoError("STREAM_STATE_ERROR", fi)
                if (sid >> 2) + 1 > self.max_streams_bidi:
                    raise ProtoError("STREAM_LIMIT_ERROR", fi)
                ent = self.streams.get(sid)
                if ent is None:
                    ent = create_stream(sid)
                set_attr(ent, "stopped", True)
                continue

            # HANDSHAKE_DONE / UNKNOWN are rejected in preflight.
            raise ProtoError("PROTOCOL_VIOLATION", fi)

    except ProtoError as err:
        rollback()
        self.fail_packet(e, p, t, err.frame, err.code)
        return

    # No CLOSE and no error: commit the packet.
    pnset.add(pkt["pn"])
    self.last_activity = t
    self.add_result(e, p, "accepted", "OK", t, None)

# -- output ----------------------------------------------------------

def build_result(self):
    out_packets = sorted(self.results,
                         key=lambda r: (r["event"], r["packet"]))
    def prefix_len(bmap):
        d = 0
        while d in bmap:
            d += 1
        return d

    streams = []
    for sid in sorted(self.streams.keys()):
        ent = self.streams[sid]
        bmap = ent["bytes"]
        d = prefix_len(bmap)
        if d:
            hx = bytes(bmap[i] for i in range(d)).hex()
        else:
            hx = ""
        streams.append({
            "id": sid,
            "highest": ent["highest"],
            "final_size": ent["final_size"],
            "reset": ent["reset"],
            "stopped": ent["stopped"],
            "delivered_hex": hx,
        })
    crypto = []
    for lvl in ("I", "H", "A"):
        st = self.crypto[lvl]
        bmap = st["bytes"]
        d = prefix_len(bmap)
        if d:
            hx = bytes(bmap[i] for i in range(d)).hex()
        else:
            hx = ""
        crypto.append({
            "level": lvl,
            "highest": st["highest"],
            "contiguous_hex": hx,
        })
    if self.state == "open":
        conn = {
            "state": "open",
            "code": None,
            "at_ms": None,
            "source": None,
            "peer_code": None,
            "last_activity_ms": self.last_activity,
        }
    else:
        conn = {
            "state": self.state,
            "code": self.code,
            "at_ms": self.at_ms,
            "source": self.source,
            "peer_code": self.peer_code,
            "last_activity_ms": self.last_activity,
        }
    return {
        "id": None,  # filled in by caller
        "packets": out_packets,
        "connection": conn,
        "keys": {
            "I": self.keys["I"],
            "H": self.keys["H"],
            "Z": self.keys["Z"],
            "A": self.keys["A"],
